$taskRoot=(Get-Location).Path
$taskArchive=Join-Path $taskRoot 'experiments/preparation-20261012-bc-loop-01'
$taskManifest=Get-Content -LiteralPath (Join-Path $taskArchive 'deliverables-manifest.json') -Raw | ConvertFrom-Json
$taskDocs=@($taskManifest | Where-Object {$_.active -and $_.path.EndsWith('.md')} | ForEach-Object {Join-Path $taskRoot $_.path})
$taskDocs+=@('README.md','process-record.md','version-map.md','file-changes.md','observation-boundaries.md') | ForEach-Object {Join-Path $taskArchive $_}
$taskLinkResults=@(foreach($taskDoc in $taskDocs){
 $taskBody=Get-Content -LiteralPath $taskDoc -Raw
 foreach($taskMatch in [regex]::Matches($taskBody,'!?\[[^\]]*\]\(([^)]+)\)')){
  $taskTarget=$taskMatch.Groups[1].Value.Trim('<','>')
  if($taskTarget -match '^(https?://|#|app://|codex://)'){continue}
  $taskTarget=($taskTarget -replace '#.*$','') -replace ':\d+$',''
  if($taskTarget -eq ''){continue}
  $taskResolved=if([IO.Path]::IsPathRooted($taskTarget)){$taskTarget}else{Join-Path (Split-Path $taskDoc -Parent) $taskTarget}
  [pscustomobject]@{document=[IO.Path]::GetRelativePath($taskRoot,$taskDoc).Replace('\','/');target=$taskTarget;exists=(Test-Path -LiteralPath $taskResolved)}
 }
})
$taskLinkResults | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/local-link-check.json') -Encoding utf8
$taskMissing=@($taskLinkResults | Where-Object {-not $_.exists -and $_.target -notin @('archive-inventory.json','environment/task-created-files.json')})
$taskSourceMissing=Test-Path -LiteralPath 'artifacts/bc-closed-loop-20261012/learner-dossier-initial.md'
[pscustomobject]@{links_checked=$taskLinkResults.Count;temporarily_pending_archive_indexes=@($taskLinkResults|Where-Object {-not $_.exists}).target;unexpected_missing_links=$taskMissing;learner_artifact_exists=$taskSourceMissing} | ConvertTo-Json -Depth 6
Get-Content -LiteralPath (Join-Path $taskArchive 'README.md') -Raw
Get-Content -LiteralPath (Join-Path $taskArchive 'file-changes.md') -Raw
